   pure subroutine one_e_grad_11(nprim_a, nprim_b, ea, ca, eb, cb, ra, rb, &
                                    natm, zatm, ratm, wt, wblk, dblk, ga, gb, gc)
      !! (1|1) one-electron gradient block: -W:dS/dR, +D:dT/dR, and
      !! +D:dV/dR (basis derivative on A and B, Hellmann-Feynman on every
      !! nucleus), contracted straight into ga (bra atom), gb (ket atom)
      !! and gc (every atom) -- no derivative matrix is ever formed. See
      !! emit_grad_class/emit_dc_vrr in scripts/gen_1e.py.
      !!
      !! gc is intent(inout) and ADDED into, never zeroed here, on
      !! purpose: the caller passes a slice of its own lane-private
      !! accumulator directly (trc_1e_grad_driver.inc's one_e_grad_item),
      !! not a per-thread local -- an automatic array sized by the RUNTIME
      !! value `natm` inside a `!$acc routine seq` body needs a per-thread
      !! dynamic stack allocation that a large `natm` (a 60-atom cluster,
      !! say) under thousands of concurrently resident threads overruns,
      !! which is exactly a CUDA_ERROR_LAUNCH_FAILED "invalid pointer
      !! dereference" and not a Fortran-level bug. Measured: that is what
      !! one_e_grad_item's own gc(3,natm) local used to be, and it is why
      !! this kernel does not get one either.
      !$acc routine seq
      integer,  intent(in)  :: nprim_a, nprim_b, natm
      real(dp), intent(in)  :: ea(nprim_a), ca(nprim_a)
      real(dp), intent(in)  :: eb(nprim_b), cb(nprim_b)
      real(dp), intent(in)  :: ra(3), rb(3)
      real(dp), intent(in)  :: zatm(natm), ratm(3, natm)
      real(dp), intent(in)  :: wt, wblk(9), dblk(9)
      real(dp), intent(out)   :: ga(3), gb(3)
      real(dp), intent(inout) :: gc(3, natm)

      integer  :: ip, jp, ic, k
      real(dp) :: al, bet, zeta, oo2z, xi, cc, tbb
      real(dp) :: px, py, pz, pax, pay, paz, pbx, pby, pbz
      real(dp) :: pcx, pcy, pcz, tval, vpref, rab2
      real(dp) :: abx, aby, abz, e0x, e0y, e0z
      real(dp) :: sx(0:2,0:3), sy(0:2,0:3), sz(0:2,0:3)
      real(dp) :: tx(0:2,0:1), ty(0:2,0:1), tz(0:2,0:1)
      real(dp) :: vn(20,0:3), vn0(20)
      real(dp) :: wx(10,0:2), wy(10,0:2), wz(10,0:2)
      real(dp) :: wx0(10), wy0(10), wz0(10)
      real(dp) :: vAp(18)
      real(dp) :: vAm(3)
      real(dp) :: vBp(18)
      real(dp) :: vBm(3)
      real(dp) :: wxt(9), wyt(9), wzt(9)
      real(dp) :: f(0:BOYS_MMAX)

      abx = ra(1) - rb(1); aby = ra(2) - rb(2); abz = ra(3) - rb(3)
      rab2 = abx*abx + aby*aby + abz*abz

      ga = 0.0_dp; gb = 0.0_dp

      do ip = 1, nprim_a
         al = ea(ip)
      do jp = 1, nprim_b
         bet = eb(jp)
         zeta = al + bet
         oo2z = 0.5_dp/zeta
         xi = al*bet/zeta
         cc = ca(ip)*cb(jp)*wt
         tbb = 2.0_dp*bet*bet

         px = (al*ra(1) + bet*rb(1))/zeta
         py = (al*ra(2) + bet*rb(2))/zeta
         pz = (al*ra(3) + bet*rb(3))/zeta
         pax = px - ra(1); pay = py - ra(2); paz = pz - ra(3)
         pbx = px - rb(1); pby = py - rb(2); pbz = pz - rb(3)

         e0x = sqrt(PI/zeta)*exp(-xi*abx*abx)
         e0y = sqrt(PI/zeta)*exp(-xi*aby*aby)
         e0z = sqrt(PI/zeta)*exp(-xi*abz*abz)

         sx(0,0) = e0x
         sx(1,0) = pax*sx(0,0)
         sx(2,0) = pax*sx(1,0) + 1.0_dp*oo2z*sx(0,0)
         sx(0,1) = pbx*sx(0,0)
         sx(1,1) = pbx*sx(1,0) + 1.0_dp*oo2z*sx(0,0)
         sx(2,1) = pbx*sx(2,0) + 2.0_dp*oo2z*sx(1,0)
         sx(0,2) = pbx*sx(0,1) + 1.0_dp*oo2z*sx(0,0)
         sx(1,2) = pbx*sx(1,1) + 1.0_dp*oo2z*sx(0,1) + 1.0_dp*oo2z*sx(1,0)
         sx(2,2) = pbx*sx(2,1) + 2.0_dp*oo2z*sx(1,1) + 1.0_dp*oo2z*sx(2,0)
         sx(0,3) = pbx*sx(0,2) + 2.0_dp*oo2z*sx(0,1)
         sx(1,3) = pbx*sx(1,2) + 1.0_dp*oo2z*sx(0,2) + 2.0_dp*oo2z*sx(1,1)
         sx(2,3) = pbx*sx(2,2) + 2.0_dp*oo2z*sx(1,2) + 2.0_dp*oo2z*sx(2,1)
         sy(0,0) = e0y
         sy(1,0) = pay*sy(0,0)
         sy(2,0) = pay*sy(1,0) + 1.0_dp*oo2z*sy(0,0)
         sy(0,1) = pby*sy(0,0)
         sy(1,1) = pby*sy(1,0) + 1.0_dp*oo2z*sy(0,0)
         sy(2,1) = pby*sy(2,0) + 2.0_dp*oo2z*sy(1,0)
         sy(0,2) = pby*sy(0,1) + 1.0_dp*oo2z*sy(0,0)
         sy(1,2) = pby*sy(1,1) + 1.0_dp*oo2z*sy(0,1) + 1.0_dp*oo2z*sy(1,0)
         sy(2,2) = pby*sy(2,1) + 2.0_dp*oo2z*sy(1,1) + 1.0_dp*oo2z*sy(2,0)
         sy(0,3) = pby*sy(0,2) + 2.0_dp*oo2z*sy(0,1)
         sy(1,3) = pby*sy(1,2) + 1.0_dp*oo2z*sy(0,2) + 2.0_dp*oo2z*sy(1,1)
         sy(2,3) = pby*sy(2,2) + 2.0_dp*oo2z*sy(1,2) + 2.0_dp*oo2z*sy(2,1)
         sz(0,0) = e0z
         sz(1,0) = paz*sz(0,0)
         sz(2,0) = paz*sz(1,0) + 1.0_dp*oo2z*sz(0,0)
         sz(0,1) = pbz*sz(0,0)
         sz(1,1) = pbz*sz(1,0) + 1.0_dp*oo2z*sz(0,0)
         sz(2,1) = pbz*sz(2,0) + 2.0_dp*oo2z*sz(1,0)
         sz(0,2) = pbz*sz(0,1) + 1.0_dp*oo2z*sz(0,0)
         sz(1,2) = pbz*sz(1,1) + 1.0_dp*oo2z*sz(0,1) + 1.0_dp*oo2z*sz(1,0)
         sz(2,2) = pbz*sz(2,1) + 2.0_dp*oo2z*sz(1,1) + 1.0_dp*oo2z*sz(2,0)
         sz(0,3) = pbz*sz(0,2) + 2.0_dp*oo2z*sz(0,1)
         sz(1,3) = pbz*sz(1,2) + 1.0_dp*oo2z*sz(0,2) + 2.0_dp*oo2z*sz(1,1)
         sz(2,3) = pbz*sz(2,2) + 2.0_dp*oo2z*sz(1,2) + 2.0_dp*oo2z*sz(2,1)

         tx(0,0) = 1.0_dp*bet*sx(0,0) - tbb*sx(0,2)
         tx(1,0) = 1.0_dp*bet*sx(1,0) - tbb*sx(1,2)
         tx(2,0) = 1.0_dp*bet*sx(2,0) - tbb*sx(2,2)
         tx(0,1) = 3.0_dp*bet*sx(0,1) - tbb*sx(0,3)
         tx(1,1) = 3.0_dp*bet*sx(1,1) - tbb*sx(1,3)
         tx(2,1) = 3.0_dp*bet*sx(2,1) - tbb*sx(2,3)
         ty(0,0) = 1.0_dp*bet*sy(0,0) - tbb*sy(0,2)
         ty(1,0) = 1.0_dp*bet*sy(1,0) - tbb*sy(1,2)
         ty(2,0) = 1.0_dp*bet*sy(2,0) - tbb*sy(2,2)
         ty(0,1) = 3.0_dp*bet*sy(0,1) - tbb*sy(0,3)
         ty(1,1) = 3.0_dp*bet*sy(1,1) - tbb*sy(1,3)
         ty(2,1) = 3.0_dp*bet*sy(2,1) - tbb*sy(2,3)
         tz(0,0) = 1.0_dp*bet*sz(0,0) - tbb*sz(0,2)
         tz(1,0) = 1.0_dp*bet*sz(1,0) - tbb*sz(1,2)
         tz(2,0) = 1.0_dp*bet*sz(2,0) - tbb*sz(2,2)
         tz(0,1) = 3.0_dp*bet*sz(0,1) - tbb*sz(0,3)
         tz(1,1) = 3.0_dp*bet*sz(1,1) - tbb*sz(1,3)
         tz(2,1) = 3.0_dp*bet*sz(2,1) - tbb*sz(2,3)

         ga(1) = ga(1) - cc*wblk(1)*((2.0_dp*al*sx(2,1) - 1.0_dp*sx(0,1))*sy(0,0)*sz(0,0)) &
                         + cc*dblk(1)*((2.0_dp*al*tx(2,1) - 1.0_dp*tx(0,1))*sy(0,0)*sz(0,0) + (2.0_dp*al*sx(2,1) - 1.0_dp*sx(0,1))*(ty(0,0)*sz(0,0) + sy(0,0)*tz(0,0)))
         gb(1) = gb(1) + cc*wblk(1)*((2.0_dp*al*sx(2,1) - 1.0_dp*sx(0,1))*sy(0,0)*sz(0,0)) &
                         - cc*dblk(1)*((2.0_dp*al*tx(2,1) - 1.0_dp*tx(0,1))*sy(0,0)*sz(0,0) + (2.0_dp*al*sx(2,1) - 1.0_dp*sx(0,1))*(ty(0,0)*sz(0,0) + sy(0,0)*tz(0,0)))
         ga(2) = ga(2) - cc*wblk(1)*((2.0_dp*al*sy(1,0))*sx(1,1)*sz(0,0)) &
                         + cc*dblk(1)*((2.0_dp*al*ty(1,0))*sx(1,1)*sz(0,0) + (2.0_dp*al*sy(1,0))*(tx(1,1)*sz(0,0) + sx(1,1)*tz(0,0)))
         gb(2) = gb(2) + cc*wblk(1)*((2.0_dp*al*sy(1,0))*sx(1,1)*sz(0,0)) &
                         - cc*dblk(1)*((2.0_dp*al*ty(1,0))*sx(1,1)*sz(0,0) + (2.0_dp*al*sy(1,0))*(tx(1,1)*sz(0,0) + sx(1,1)*tz(0,0)))
         ga(3) = ga(3) - cc*wblk(1)*((2.0_dp*al*sz(1,0))*sx(1,1)*sy(0,0)) &
                         + cc*dblk(1)*((2.0_dp*al*tz(1,0))*sx(1,1)*sy(0,0) + (2.0_dp*al*sz(1,0))*(tx(1,1)*sy(0,0) + sx(1,1)*ty(0,0)))
         gb(3) = gb(3) + cc*wblk(1)*((2.0_dp*al*sz(1,0))*sx(1,1)*sy(0,0)) &
                         - cc*dblk(1)*((2.0_dp*al*tz(1,0))*sx(1,1)*sy(0,0) + (2.0_dp*al*sz(1,0))*(tx(1,1)*sy(0,0) + sx(1,1)*ty(0,0)))
         ga(1) = ga(1) - cc*wblk(2)*((2.0_dp*al*sx(1,1))*sy(1,0)*sz(0,0)) &
                         + cc*dblk(2)*((2.0_dp*al*tx(1,1))*sy(1,0)*sz(0,0) + (2.0_dp*al*sx(1,1))*(ty(1,0)*sz(0,0) + sy(1,0)*tz(0,0)))
         gb(1) = gb(1) + cc*wblk(2)*((2.0_dp*al*sx(1,1))*sy(1,0)*sz(0,0)) &
                         - cc*dblk(2)*((2.0_dp*al*tx(1,1))*sy(1,0)*sz(0,0) + (2.0_dp*al*sx(1,1))*(ty(1,0)*sz(0,0) + sy(1,0)*tz(0,0)))
         ga(2) = ga(2) - cc*wblk(2)*((2.0_dp*al*sy(2,0) - 1.0_dp*sy(0,0))*sx(0,1)*sz(0,0)) &
                         + cc*dblk(2)*((2.0_dp*al*ty(2,0) - 1.0_dp*ty(0,0))*sx(0,1)*sz(0,0) + (2.0_dp*al*sy(2,0) - 1.0_dp*sy(0,0))*(tx(0,1)*sz(0,0) + sx(0,1)*tz(0,0)))
         gb(2) = gb(2) + cc*wblk(2)*((2.0_dp*al*sy(2,0) - 1.0_dp*sy(0,0))*sx(0,1)*sz(0,0)) &
                         - cc*dblk(2)*((2.0_dp*al*ty(2,0) - 1.0_dp*ty(0,0))*sx(0,1)*sz(0,0) + (2.0_dp*al*sy(2,0) - 1.0_dp*sy(0,0))*(tx(0,1)*sz(0,0) + sx(0,1)*tz(0,0)))
         ga(3) = ga(3) - cc*wblk(2)*((2.0_dp*al*sz(1,0))*sx(0,1)*sy(1,0)) &
                         + cc*dblk(2)*((2.0_dp*al*tz(1,0))*sx(0,1)*sy(1,0) + (2.0_dp*al*sz(1,0))*(tx(0,1)*sy(1,0) + sx(0,1)*ty(1,0)))
         gb(3) = gb(3) + cc*wblk(2)*((2.0_dp*al*sz(1,0))*sx(0,1)*sy(1,0)) &
