         ga(1) = ga(1) - cc*wblk(3)*((2.0_dp*al*sx(1,1))*sy(0,0)*sz(1,0)) &
                         + cc*dblk(3)*((2.0_dp*al*tx(1,1))*sy(0,0)*sz(1,0) + (2.0_dp*al*sx(1,1))*(ty(0,0)*sz(1,0) + sy(0,0)*tz(1,0)))
         gb(1) = gb(1) + cc*wblk(3)*((2.0_dp*al*sx(1,1))*sy(0,0)*sz(1,0)) &
                         - cc*dblk(3)*((2.0_dp*al*tx(1,1))*sy(0,0)*sz(1,0) + (2.0_dp*al*sx(1,1))*(ty(0,0)*sz(1,0) + sy(0,0)*tz(1,0)))
         ga(2) = ga(2) - cc*wblk(3)*((2.0_dp*al*sy(1,0))*sx(0,1)*sz(1,0)) &
                         + cc*dblk(3)*((2.0_dp*al*ty(1,0))*sx(0,1)*sz(1,0) + (2.0_dp*al*sy(1,0))*(tx(0,1)*sz(1,0) + sx(0,1)*tz(1,0)))
         gb(2) = gb(2) + cc*wblk(3)*((2.0_dp*al*sy(1,0))*sx(0,1)*sz(1,0)) &
                         - cc*dblk(3)*((2.0_dp*al*ty(1,0))*sx(0,1)*sz(1,0) + (2.0_dp*al*sy(1,0))*(tx(0,1)*sz(1,0) + sx(0,1)*tz(1,0)))
         ga(3) = ga(3) - cc*wblk(3)*((2.0_dp*al*sz(2,0) - 1.0_dp*sz(0,0))*sx(0,1)*sy(0,0)) &
                         + cc*dblk(3)*((2.0_dp*al*tz(2,0) - 1.0_dp*tz(0,0))*sx(0,1)*sy(0,0) + (2.0_dp*al*sz(2,0) - 1.0_dp*sz(0,0))*(tx(0,1)*sy(0,0) + sx(0,1)*ty(0,0)))
         gb(3) = gb(3) + cc*wblk(3)*((2.0_dp*al*sz(2,0) - 1.0_dp*sz(0,0))*sx(0,1)*sy(0,0)) &
                         - cc*dblk(3)*((2.0_dp*al*tz(2,0) - 1.0_dp*tz(0,0))*sx(0,1)*sy(0,0) + (2.0_dp*al*sz(2,0) - 1.0_dp*sz(0,0))*(tx(0,1)*sy(0,0) + sx(0,1)*ty(0,0)))
