                         + cc*dblk(4)*((2.0_dp*al*tx(2,0) - 1.0_dp*tx(0,0))*sy(0,1)*sz(0,0) + (2.0_dp*al*sx(2,0) - 1.0_dp*sx(0,0))*(ty(0,1)*sz(0,0) + sy(0,1)*tz(0,0)))
         gb(1) = gb(1) + cc*wblk(4)*((2.0_dp*al*sx(2,0) - 1.0_dp*sx(0,0))*sy(0,1)*sz(0,0)) &
                         - cc*dblk(4)*((2.0_dp*al*tx(2,0) - 1.0_dp*tx(0,0))*sy(0,1)*sz(0,0) + (2.0_dp*al*sx(2,0) - 1.0_dp*sx(0,0))*(ty(0,1)*sz(0,0) + sy(0,1)*tz(0,0)))
         ga(2) = ga(2) - cc*wblk(4)*((2.0_dp*al*sy(1,1))*sx(1,0)*sz(0,0)) &
                         + cc*dblk(4)*((2.0_dp*al*ty(1,1))*sx(1,0)*sz(0,0) + (2.0_dp*al*sy(1,1))*(tx(1,0)*sz(0,0) + sx(1,0)*tz(0,0)))
         gb(2) = gb(2) + cc*wblk(4)*((2.0_dp*al*sy(1,1))*sx(1,0)*sz(0,0)) &
                         - cc*dblk(4)*((2.0_dp*al*ty(1,1))*sx(1,0)*sz(0,0) + (2.0_dp*al*sy(1,1))*(tx(1,0)*sz(0,0) + sx(1,0)*tz(0,0)))
         ga(3) = ga(3) - cc*wblk(4)*((2.0_dp*al*sz(1,0))*sx(1,0)*sy(0,1)) &
                         + cc*dblk(4)*((2.0_dp*al*tz(1,0))*sx(1,0)*sy(0,1) + (2.0_dp*al*sz(1,0))*(tx(1,0)*sy(0,1) + sx(1,0)*ty(0,1)))
         gb(3) = gb(3) + cc*wblk(4)*((2.0_dp*al*sz(1,0))*sx(1,0)*sy(0,1)) &
                         - cc*dblk(4)*((2.0_dp*al*tz(1,0))*sx(1,0)*sy(0,1) + (2.0_dp*al*sz(1,0))*(tx(1,0)*sy(0,1) + sx(1,0)*ty(0,1)))
         ga(1) = ga(1) - cc*wblk(5)*((2.0_dp*al*sx(1,0))*sy(1,1)*sz(0,0)) &
                         + cc*dblk(5)*((2.0_dp*al*tx(1,0))*sy(1,1)*sz(0,0) + (2.0_dp*al*sx(1,0))*(ty(1,1)*sz(0,0) + sy(1,1)*tz(0,0)))
         gb(1) = gb(1) + cc*wblk(5)*((2.0_dp*al*sx(1,0))*sy(1,1)*sz(0,0)) &
                         - cc*dblk(5)*((2.0_dp*al*tx(1,0))*sy(1,1)*sz(0,0) + (2.0_dp*al*sx(1,0))*(ty(1,1)*sz(0,0) + sy(1,1)*tz(0,0)))
         ga(2) = ga(2) - cc*wblk(5)*((2.0_dp*al*sy(2,1) - 1.0_dp*sy(0,1))*sx(0,0)*sz(0,0)) &
                         + cc*dblk(5)*((2.0_dp*al*ty(2,1) - 1.0_dp*ty(0,1))*sx(0,0)*sz(0,0) + (2.0_dp*al*sy(2,1) - 1.0_dp*sy(0,1))*(tx(0,0)*sz(0,0) + sx(0,0)*tz(0,0)))
         gb(2) = gb(2) + cc*wblk(5)*((2.0_dp*al*sy(2,1) - 1.0_dp*sy(0,1))*sx(0,0)*sz(0,0)) &
                         - cc*dblk(5)*((2.0_dp*al*ty(2,1) - 1.0_dp*ty(0,1))*sx(0,0)*sz(0,0) + (2.0_dp*al*sy(2,1) - 1.0_dp*sy(0,1))*(tx(0,0)*sz(0,0) + sx(0,0)*tz(0,0)))
         ga(3) = ga(3) - cc*wblk(5)*((2.0_dp*al*sz(1,0))*sx(0,0)*sy(1,1)) &
                         + cc*dblk(5)*((2.0_dp*al*tz(1,0))*sx(0,0)*sy(1,1) + (2.0_dp*al*sz(1,0))*(tx(0,0)*sy(1,1) + sx(0,0)*ty(1,1)))
         gb(3) = gb(3) + cc*wblk(5)*((2.0_dp*al*sz(1,0))*sx(0,0)*sy(1,1)) &
                         - cc*dblk(5)*((2.0_dp*al*tz(1,0))*sx(0,0)*sy(1,1) + (2.0_dp*al*sz(1,0))*(tx(0,0)*sy(1,1) + sx(0,0)*ty(1,1)))
         ga(1) = ga(1) - cc*wblk(6)*((2.0_dp*al*sx(1,0))*sy(0,1)*sz(1,0)) &
                         + cc*dblk(6)*((2.0_dp*al*tx(1,0))*sy(0,1)*sz(1,0) + (2.0_dp*al*sx(1,0))*(ty(0,1)*sz(1,0) + sy(0,1)*tz(1,0)))
         gb(1) = gb(1) + cc*wblk(6)*((2.0_dp*al*sx(1,0))*sy(0,1)*sz(1,0)) &
                         - cc*dblk(6)*((2.0_dp*al*tx(1,0))*sy(0,1)*sz(1,0) + (2.0_dp*al*sx(1,0))*(ty(0,1)*sz(1,0) + sy(0,1)*tz(1,0)))
         ga(2) = ga(2) - cc*wblk(6)*((2.0_dp*al*sy(1,1))*sx(0,0)*sz(1,0)) &
                         + cc*dblk(6)*((2.0_dp*al*ty(1,1))*sx(0,0)*sz(1,0) + (2.0_dp*al*sy(1,1))*(tx(0,0)*sz(1,0) + sx(0,0)*tz(1,0)))
         gb(2) = gb(2) + cc*wblk(6)*((2.0_dp*al*sy(1,1))*sx(0,0)*sz(1,0)) &
                         - cc*dblk(6)*((2.0_dp*al*ty(1,1))*sx(0,0)*sz(1,0) + (2.0_dp*al*sy(1,1))*(tx(0,0)*sz(1,0) + sx(0,0)*tz(1,0)))
         ga(3) = ga(3) - cc*wblk(6)*((2.0_dp*al*sz(2,0) - 1.0_dp*sz(0,0))*sx(0,0)*sy(0,1)) &
                         + cc*dblk(6)*((2.0_dp*al*tz(2,0) - 1.0_dp*tz(0,0))*sx(0,0)*sy(0,1) + (2.0_dp*al*sz(2,0) - 1.0_dp*sz(0,0))*(tx(0,0)*sy(0,1) + sx(0,0)*ty(0,1)))
         gb(3) = gb(3) + cc*wblk(6)*((2.0_dp*al*sz(2,0) - 1.0_dp*sz(0,0))*sx(0,0)*sy(0,1)) &
                         - cc*dblk(6)*((2.0_dp*al*tz(2,0) - 1.0_dp*tz(0,0))*sx(0,0)*sy(0,1) + (2.0_dp*al*sz(2,0) - 1.0_dp*sz(0,0))*(tx(0,0)*sy(0,1) + sx(0,0)*ty(0,1)))
         ga(1) = ga(1) - cc*wblk(7)*((2.0_dp*al*sx(2,0) - 1.0_dp*sx(0,0))*sy(0,0)*sz(0,1)) &
                         + cc*dblk(7)*((2.0_dp*al*tx(2,0) - 1.0_dp*tx(0,0))*sy(0,0)*sz(0,1) + (2.0_dp*al*sx(2,0) - 1.0_dp*sx(0,0))*(ty(0,0)*sz(0,1) + sy(0,0)*tz(0,1)))
         gb(1) = gb(1) + cc*wblk(7)*((2.0_dp*al*sx(2,0) - 1.0_dp*sx(0,0))*sy(0,0)*sz(0,1)) &
                         - cc*dblk(7)*((2.0_dp*al*tx(2,0) - 1.0_dp*tx(0,0))*sy(0,0)*sz(0,1) + (2.0_dp*al*sx(2,0) - 1.0_dp*sx(0,0))*(ty(0,0)*sz(0,1) + sy(0,0)*tz(0,1)))
         ga(2) = ga(2) - cc*wblk(7)*((2.0_dp*al*sy(1,0))*sx(1,0)*sz(0,1)) &
                         + cc*dblk(7)*((2.0_dp*al*ty(1,0))*sx(1,0)*sz(0,1) + (2.0_dp*al*sy(1,0))*(tx(1,0)*sz(0,1) + sx(1,0)*tz(0,1)))
         gb(2) = gb(2) + cc*wblk(7)*((2.0_dp*al*sy(1,0))*sx(1,0)*sz(0,1)) &
                         - cc*dblk(7)*((2.0_dp*al*ty(1,0))*sx(1,0)*sz(0,1) + (2.0_dp*al*sy(1,0))*(tx(1,0)*sz(0,1) + sx(1,0)*tz(0,1)))
         ga(3) = ga(3) - cc*wblk(7)*((2.0_dp*al*sz(1,1))*sx(1,0)*sy(0,0)) &
                         + cc*dblk(7)*((2.0_dp*al*tz(1,1))*sx(1,0)*sy(0,0) + (2.0_dp*al*sz(1,1))*(tx(1,0)*sy(0,0) + sx(1,0)*ty(0,0)))
         gb(3) = gb(3) + cc*wblk(7)*((2.0_dp*al*sz(1,1))*sx(1,0)*sy(0,0)) &
                         - cc*dblk(7)*((2.0_dp*al*tz(1,1))*sx(1,0)*sy(0,0) + (2.0_dp*al*sz(1,1))*(tx(1,0)*sy(0,0) + sx(1,0)*ty(0,0)))
         ga(1) = ga(1) - cc*wblk(8)*((2.0_dp*al*sx(1,0))*sy(1,0)*sz(0,1)) &
                         + cc*dblk(8)*((2.0_dp*al*tx(1,0))*sy(1,0)*sz(0,1) + (2.0_dp*al*sx(1,0))*(ty(1,0)*sz(0,1) + sy(1,0)*tz(0,1)))
         gb(1) = gb(1) + cc*wblk(8)*((2.0_dp*al*sx(1,0))*sy(1,0)*sz(0,1)) &
                         - cc*dblk(8)*((2.0_dp*al*tx(1,0))*sy(1,0)*sz(0,1) + (2.0_dp*al*sx(1,0))*(ty(1,0)*sz(0,1) + sy(1,0)*tz(0,1)))
         ga(2) = ga(2) - cc*wblk(8)*((2.0_dp*al*sy(2,0) - 1.0_dp*sy(0,0))*sx(0,0)*sz(0,1)) &
                         + cc*dblk(8)*((2.0_dp*al*ty(2,0) - 1.0_dp*ty(0,0))*sx(0,0)*sz(0,1) + (2.0_dp*al*sy(2,0) - 1.0_dp*sy(0,0))*(tx(0,0)*sz(0,1) + sx(0,0)*tz(0,1)))
         gb(2) = gb(2) + cc*wblk(8)*((2.0_dp*al*sy(2,0) - 1.0_dp*sy(0,0))*sx(0,0)*sz(0,1)) &
                         - cc*dblk(8)*((2.0_dp*al*ty(2,0) - 1.0_dp*ty(0,0))*sx(0,0)*sz(0,1) + (2.0_dp*al*sy(2,0) - 1.0_dp*sy(0,0))*(tx(0,0)*sz(0,1) + sx(0,0)*tz(0,1)))
         ga(3) = ga(3) - cc*wblk(8)*((2.0_dp*al*sz(1,1))*sx(0,0)*sy(1,0)) &
                         + cc*dblk(8)*((2.0_dp*al*tz(1,1))*sx(0,0)*sy(1,0) + (2.0_dp*al*sz(1,1))*(tx(0,0)*sy(1,0) + sx(0,0)*ty(1,0)))
         gb(3) = gb(3) + cc*wblk(8)*((2.0_dp*al*sz(1,1))*sx(0,0)*sy(1,0)) &
                         - cc*dblk(8)*((2.0_dp*al*tz(1,1))*sx(0,0)*sy(1,0) + (2.0_dp*al*sz(1,1))*(tx(0,0)*sy(1,0) + sx(0,0)*ty(1,0)))
         ga(1) = ga(1) - cc*wblk(9)*((2.0_dp*al*sx(1,0))*sy(0,0)*sz(1,1)) &
                         + cc*dblk(9)*((2.0_dp*al*tx(1,0))*sy(0,0)*sz(1,1) + (2.0_dp*al*sx(1,0))*(ty(0,0)*sz(1,1) + sy(0,0)*tz(1,1)))
         gb(1) = gb(1) + cc*wblk(9)*((2.0_dp*al*sx(1,0))*sy(0,0)*sz(1,1)) &
                         - cc*dblk(9)*((2.0_dp*al*tx(1,0))*sy(0,0)*sz(1,1) + (2.0_dp*al*sx(1,0))*(ty(0,0)*sz(1,1) + sy(0,0)*tz(1,1)))
         ga(2) = ga(2) - cc*wblk(9)*((2.0_dp*al*sy(1,0))*sx(0,0)*sz(1,1)) &
                         + cc*dblk(9)*((2.0_dp*al*ty(1,0))*sx(0,0)*sz(1,1) + (2.0_dp*al*sy(1,0))*(tx(0,0)*sz(1,1) + sx(0,0)*tz(1,1)))
         gb(2) = gb(2) + cc*wblk(9)*((2.0_dp*al*sy(1,0))*sx(0,0)*sz(1,1)) &
                         - cc*dblk(9)*((2.0_dp*al*ty(1,0))*sx(0,0)*sz(1,1) + (2.0_dp*al*sy(1,0))*(tx(0,0)*sz(1,1) + sx(0,0)*tz(1,1)))
         ga(3) = ga(3) - cc*wblk(9)*((2.0_dp*al*sz(2,1) - 1.0_dp*sz(0,1))*sx(0,0)*sy(0,0)) &
                         + cc*dblk(9)*((2.0_dp*al*tz(2,1) - 1.0_dp*tz(0,1))*sx(0,0)*sy(0,0) + (2.0_dp*al*sz(2,1) - 1.0_dp*sz(0,1))*(tx(0,0)*sy(0,0) + sx(0,0)*ty(0,0)))
         gb(3) = gb(3) + cc*wblk(9)*((2.0_dp*al*sz(2,1) - 1.0_dp*sz(0,1))*sx(0,0)*sy(0,0)) &
                         - cc*dblk(9)*((2.0_dp*al*tz(2,1) - 1.0_dp*tz(0,1))*sx(0,0)*sy(0,0) + (2.0_dp*al*sz(2,1) - 1.0_dp*sz(0,1))*(tx(0,0)*sy(0,0) + sx(0,0)*ty(0,0)))

         ! --- nuclear attraction: basis derivative + Hellmann-Feynman, per nucleus ---
         vpref = 2.0_dp*PI/zeta*exp(-xi*rab2)
         do ic = 1, natm
            pcx = px - ratm(1, ic)
            pcy = py - ratm(2, ic)
            pcz = pz - ratm(3, ic)
            tval = zeta*(pcx*pcx + pcy*pcy + pcz*pcz)
            call boys_eval(3, tval, f)

            ! --- m = 3 ---
            vn(1,3) = vpref*f(3)
            ! --- m = 2 ---
            vn(1,2) = vpref*f(2)
            vn(2,2) = pax*vn(1,2) - pcx*vn(1,3)
            vn(3,2) = pay*vn(1,2) - pcy*vn(1,3)
            vn(4,2) = paz*vn(1,2) - pcz*vn(1,3)
            ! --- m = 1 ---
            vn(1,1) = vpref*f(1)
            vn(2,1) = pax*vn(1,1) - pcx*vn(1,2)
            vn(3,1) = pay*vn(1,1) - pcy*vn(1,2)
            vn(4,1) = paz*vn(1,1) - pcz*vn(1,2)
            vn(5,1) = pax*vn(2,1) - pcx*vn(2,2) &
               + 1.0_dp*oo2z*(vn(1,1) - vn(1,2))
            vn(6,1) = pax*vn(3,1) - pcx*vn(3,2)
            vn(7,1) = pax*vn(4,1) - pcx*vn(4,2)
            vn(8,1) = pay*vn(3,1) - pcy*vn(3,2) &
               + 1.0_dp*oo2z*(vn(1,1) - vn(1,2))
            vn(9,1) = pay*vn(4,1) - pcy*vn(4,2)
            vn(10,1) = paz*vn(4,1) - pcz*vn(4,2) &
               + 1.0_dp*oo2z*(vn(1,1) - vn(1,2))
            ! --- m = 0 ---
            vn(1,0) = vpref*f(0)
            vn(2,0) = pax*vn(1,0) - pcx*vn(1,1)
            vn(3,0) = pay*vn(1,0) - pcy*vn(1,1)
            vn(4,0) = paz*vn(1,0) - pcz*vn(1,1)
            vn(5,0) = pax*vn(2,0) - pcx*vn(2,1) &
               + 1.0_dp*oo2z*(vn(1,0) - vn(1,1))
            vn(6,0) = pax*vn(3,0) - pcx*vn(3,1)
            vn(7,0) = pax*vn(4,0) - pcx*vn(4,1)
            vn(8,0) = pay*vn(3,0) - pcy*vn(3,1) &
               + 1.0_dp*oo2z*(vn(1,0) - vn(1,1))
            vn(9,0) = pay*vn(4,0) - pcy*vn(4,1)
            vn(10,0) = paz*vn(4,0) - pcz*vn(4,1) &
               + 1.0_dp*oo2z*(vn(1,0) - vn(1,1))
            vn(11,0) = pax*vn(5,0) - pcx*vn(5,1) &
               + 2.0_dp*oo2z*(vn(2,0) - vn(2,1))
            vn(12,0) = pax*vn(6,0) - pcx*vn(6,1) &
               + 1.0_dp*oo2z*(vn(3,0) - vn(3,1))
            vn(13,0) = pax*vn(7,0) - pcx*vn(7,1) &
               + 1.0_dp*oo2z*(vn(4,0) - vn(4,1))
            vn(14,0) = pax*vn(8,0) - pcx*vn(8,1)
            vn(15,0) = pax*vn(9,0) - pcx*vn(9,1)
            vn(16,0) = pax*vn(10,0) - pcx*vn(10,1)
            vn(17,0) = pay*vn(8,0) - pcy*vn(8,1) &
               + 2.0_dp*oo2z*(vn(3,0) - vn(3,1))
            vn(18,0) = pay*vn(9,0) - pcy*vn(9,1) &
               + 1.0_dp*oo2z*(vn(4,0) - vn(4,1))
            vn(19,0) = pay*vn(10,0) - pcy*vn(10,1)
            vn(20,0) = paz*vn(10,0) - pcz*vn(10,1) &
               + 2.0_dp*oo2z*(vn(4,0) - vn(4,1))

            ! --- dV/dC, m = 2 ---
            wx(1,2) = 2.0_dp*zeta*pcx*vn(1,3)
            wy(1,2) = 2.0_dp*zeta*pcy*vn(1,3)
            wz(1,2) = 2.0_dp*zeta*pcz*vn(1,3)
            ! --- dV/dC, m = 1 ---
            wx(1,1) = 2.0_dp*zeta*pcx*vn(1,2)
            wy(1,1) = 2.0_dp*zeta*pcy*vn(1,2)
            wz(1,1) = 2.0_dp*zeta*pcz*vn(1,2)
            wx(2,1) = pax*wx(1,1) - pcx*wx(1,2) &
               + vn(1,2)
            wy(2,1) = pax*wy(1,1) - pcx*wy(1,2)
            wz(2,1) = pax*wz(1,1) - pcx*wz(1,2)
            wx(3,1) = pay*wx(1,1) - pcy*wx(1,2)
            wy(3,1) = pay*wy(1,1) - pcy*wy(1,2) &
               + vn(1,2)
            wz(3,1) = pay*wz(1,1) - pcy*wz(1,2)
            wx(4,1) = paz*wx(1,1) - pcz*wx(1,2)
            wy(4,1) = paz*wy(1,1) - pcz*wy(1,2)
            wz(4,1) = paz*wz(1,1) - pcz*wz(1,2) &
               + vn(1,2)
            ! --- dV/dC, m = 0 ---
            wx(1,0) = 2.0_dp*zeta*pcx*vn(1,1)
            wy(1,0) = 2.0_dp*zeta*pcy*vn(1,1)
            wz(1,0) = 2.0_dp*zeta*pcz*vn(1,1)
            wx(2,0) = pax*wx(1,0) - pcx*wx(1,1) &
               + vn(1,1)
            wy(2,0) = pax*wy(1,0) - pcx*wy(1,1)
            wz(2,0) = pax*wz(1,0) - pcx*wz(1,1)
            wx(3,0) = pay*wx(1,0) - pcy*wx(1,1)
            wy(3,0) = pay*wy(1,0) - pcy*wy(1,1) &
               + vn(1,1)
            wz(3,0) = pay*wz(1,0) - pcy*wz(1,1)
            wx(4,0) = paz*wx(1,0) - pcz*wx(1,1)
            wy(4,0) = paz*wy(1,0) - pcz*wy(1,1)
            wz(4,0) = paz*wz(1,0) - pcz*wz(1,1) &
               + vn(1,1)
            wx(5,0) = pax*wx(2,0) - pcx*wx(2,1) &
               + vn(2,1) &
               + 1.0_dp*oo2z*(wx(1,0) - wx(1,1))
            wy(5,0) = pax*wy(2,0) - pcx*wy(2,1) &
               + 1.0_dp*oo2z*(wy(1,0) - wy(1,1))
            wz(5,0) = pax*wz(2,0) - pcx*wz(2,1) &
               + 1.0_dp*oo2z*(wz(1,0) - wz(1,1))
            wx(6,0) = pax*wx(3,0) - pcx*wx(3,1) &
               + vn(3,1)
            wy(6,0) = pax*wy(3,0) - pcx*wy(3,1)
            wz(6,0) = pax*wz(3,0) - pcx*wz(3,1)
            wx(7,0) = pax*wx(4,0) - pcx*wx(4,1) &
               + vn(4,1)
            wy(7,0) = pax*wy(4,0) - pcx*wy(4,1)
            wz(7,0) = pax*wz(4,0) - pcx*wz(4,1)
            wx(8,0) = pay*wx(3,0) - pcy*wx(3,1) &
               + 1.0_dp*oo2z*(wx(1,0) - wx(1,1))
            wy(8,0) = pay*wy(3,0) - pcy*wy(3,1) &
               + vn(3,1) &
               + 1.0_dp*oo2z*(wy(1,0) - wy(1,1))
            wz(8,0) = pay*wz(3,0) - pcy*wz(3,1) &
               + 1.0_dp*oo2z*(wz(1,0) - wz(1,1))
            wx(9,0) = pay*wx(4,0) - pcy*wx(4,1)
            wy(9,0) = pay*wy(4,0) - pcy*wy(4,1) &
               + vn(4,1)
            wz(9,0) = pay*wz(4,0) - pcy*wz(4,1)
            wx(10,0) = paz*wx(4,0) - pcz*wx(4,1) &
               + 1.0_dp*oo2z*(wx(1,0) - wx(1,1))
